import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import toast from 'react-hot-toast';

import {
  updateFormField,
  createComplaint,
  updateComplaint,
  setFormData,
} from '../../store/slices/complaintSlice';

const EMPTY_FORM = {
  complainant_name: '',
  complainant_company: '',
  complainant_email: '',
  complainant_phone: '',
  product_name: '',
  batch_number: '',
  manufacturing_date: '',
  expiry_date: '',
  quantity_affected: '',
  date_received: '',
  category: '',
  description: '',
  severity: '',
  assigned_to: '',
  status: 'Open',
  source: 'Manual',
};

const CATEGORIES = [
  'Quality',
  'Packaging',
  'Efficacy',
  'Safety',
  'Labeling',
  'Other',
];

const SEVERITIES = [
  'Critical',
  'Major',
  'Minor',
];

const STATUSES = [
  'Open',
  'Under Investigation',
  'Pending CAPA',
  'Closed',
];

function Field({
  label,
  field,
  value,
  onChange,
  type = 'text',
  options,
}) {
  return (
    <div>

      <label className="block mb-1 text-xs font-medium text-gray-500">
        {label}
      </label>

      {options ? (
        <select
          value={value}
          onChange={(e) => onChange(field, e.target.value)}
          className="w-full border rounded-lg px-3 py-2"
        >
          <option value="">Select...</option>

          {options.map((item) => (
            <option key={item} value={item}>
              {item}
            </option>
          ))}

        </select>
      ) : type === 'textarea' ? (
        <textarea
          value={value}
          onChange={(e) => onChange(field, e.target.value)}
          className="w-full border rounded-lg px-3 py-2 h-24"
        />
      ) : (
        <input
          type={type}
          value={value}
          onChange={(e) => onChange(field, e.target.value)}
          className="w-full border rounded-lg px-3 py-2"
        />
      )}

    </div>
  );
}

export default function ComplaintForm({ isEdit = false }) {

  const dispatch = useDispatch();

  const form = useSelector(
    (state) => state.complaints.currentComplaint
  );

  const handleChange = (field, value) => {
    dispatch(updateFormField({ field, value }));
  };

  const clearForm = () => {
    dispatch(setFormData(EMPTY_FORM));
    toast.success('Form cleared');
  };

  const handleSave = async () => {
    try {

      if (isEdit && form.id) {

        await dispatch(
          updateComplaint({
            id: form.id,
            data: form,
          })
        ).unwrap();

        toast.success('Complaint updated');

      } else {

        await dispatch(createComplaint(form)).unwrap();

        toast.success('Complaint created');

        dispatch(setFormData(EMPTY_FORM));
      }

    } catch {

      toast.error('Unable to save complaint');

    }
  };

  return (
    <div className="bg-white rounded-xl border p-6">

      <h2 className="text-xl font-semibold mb-6">
        {isEdit ? 'Edit Complaint' : 'Log Complaint'}
      </h2>

      <div className="grid md:grid-cols-2 gap-4">

        <Field
          label="Customer Name"
          field="complainant_name"
          value={form.complainant_name}
          onChange={handleChange}
        />

        <Field
          label="Company"
          field="complainant_company"
          value={form.complainant_company}
          onChange={handleChange}
        />

        <Field
          label="Email"
          field="complainant_email"
          value={form.complainant_email}
          onChange={handleChange}
        />

        <Field
          label="Phone"
          field="complainant_phone"
          value={form.complainant_phone}
          onChange={handleChange}
        />

        <Field
          label="Product"
          field="product_name"
          value={form.product_name}
          onChange={handleChange}
        />

        <Field
          label="Batch"
          field="batch_number"
          value={form.batch_number}
          onChange={handleChange}
        />

        <Field
          label="Category"
          field="category"
          value={form.category}
          options={CATEGORIES}
          onChange={handleChange}
        />

        <Field
          label="Severity"
          field="severity"
          value={form.severity}
          options={SEVERITIES}
          onChange={handleChange}
        />

        <div className="md:col-span-2">
          <Field
            label="Description"
            field="description"
            value={form.description}
            type="textarea"
            onChange={handleChange}
          />
        </div>

        <Field
          label="Assigned To"
          field="assigned_to"
          value={form.assigned_to}
          onChange={handleChange}
        />

        <Field
          label="Status"
          field="status"
          value={form.status}
          options={STATUSES}
          onChange={handleChange}
        />

      </div>

      <div className="flex justify-end gap-3 mt-6">

        <button
          onClick={clearForm}
          className="border px-4 py-2 rounded-lg"
        >
          Clear
        </button>

        <button
          onClick={handleSave}
          className="bg-blue-600 text-white px-5 py-2 rounded-lg"
        >
          {isEdit ? 'Update' : 'Save'}
        </button>

      </div>

    </div>
  );
}
